#!/usr/bin/env python3
"""Build the single-file, offline inspection atlas from verified map assets."""
from pathlib import Path
import json
import re
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parent
DATA = json.loads((ROOT / 'data/map-data.json').read_text(encoding='utf-8'))
NS = '{http://www.w3.org/2000/svg}'
ET.register_namespace('', 'http://www.w3.org/2000/svg')
ET.register_namespace('xlink', 'http://www.w3.org/1999/xlink')


def embedded_svg(filename, prefix, layer):
    root = ET.parse(ROOT / filename).getroot()
    ids = {node.attrib['id']: prefix + node.attrib['id'] for node in root.iter() if 'id' in node.attrib}
    for node in root.iter():
        for key, value in list(node.attrib.items()):
            if key == 'id':
                node.set(key, ids[value])
            elif value.startswith('#') and value[1:] in ids:
                node.set(key, '#' + ids[value[1:]])
            elif 'url(#' in value:
                node.set(key, re.sub(r'url\(#([^)]*)\)', lambda m: 'url(#' + ids.get(m[1], m[1]) + ')', value))
    x, y, w, h = DATA['viewBox']
    root.set('id', layer)
    for key, val in zip(('x', 'y', 'width', 'height'), (x, y, w, h)):
        root.set(key, str(val))
    root.set('aria-hidden', 'true')
    root.set('pointer-events', 'none')
    if layer == 'adminArt':
        root.set('style', 'display:none')
    return ET.tostring(root, encoding='unicode')


